FROM s;
PREPARE content_json(text, text) AS
SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM log_regex_json_write.access_log_json_w), 'distinct', (SELECT count(DISTINCT log_id) FROM log_regex_json_write.access_log_json_w), 'matched', count(*),
    'updated_expected', count(e.log_id),
