    'updated_expected_text_bytes', coalesce(sum(octet_length(e.new_text)) FILTER (WHERE e.log_id IS NOT NULL), 0),
    'md5', md5(string_agg(w.doc::text, chr(10) ORDER BY w.log_id)))::text AS json
